export type SearchHit = {
    /**
     * Ranking signal, never a truth or trust score.
     */
    score: number;
    /**
     * Matching text.
     */
    snippet: string;
    /**
     * Reopenable citation.
     */
    source: SourceReference;
    /**
     * Item title.
     */
    title: string;
};

/**
 * Search the workspace at one revision with explicit scope and pagination.
 */
export type SearchRequest = {
    /**
     * Requested revision selector; latest is resolved once before reading.
     */
    at: At;
    /**
     * Limit to a relative folder.
     */
    folder?: string | null;
    /**
     * Include historical lifecycle items.
     */
    include_archived: boolean;
    /**
     * Bounded pagination with an opaque cursor.
     */
    page: PageRequest;
    /**
     * Search expression; not executable SQL.
     */
    query: string;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * A paged authorized search result.
 */
export type SearchResponse = {
    /**
     * Matching excerpts.
     */
    hits: Array<SearchHit>;
    /**
     * Continuation cursor.
     */
    next_cursor?: string | null;
    /**
     * Resolved revision.
     */
    revision: Revision;
};

/**
 * Explicit bounded source selection.
 */
export type Selection = {
    kind: 'all';
} | {
    kind: 'lines';
    /**
     * Range.
     */
    range: TextRange;
} | {
    kind: 'pages';
    /**
     * Range.
     */
    range: PageRange;
} | {
    kind: 'cells';
    /**
     * Range.
     */
    range: CellRange;
} | {
    /**
     * Heading.
     */
    heading: string;
    kind: 'section';
};

/**
 * Current identity and capability summary without credentials.
 */
export type SessionResponse = {
    /**
     * Browser writes require a same-origin anti-CSRF token.
     */
    csrf_required: boolean;
    /**
     * Authenticated caller.
     */
    principal: Principal;
};

/**
 * Retire or reactivate an item without claiming a business decision.
 */
export type SetLifecycleRequest = {
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Stable application item identity; paths remain the portable OKF identity.
     */
    item_id: ItemId;
    /**
     * Requested lifecycle.
     */
    lifecycle: Lifecycle;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * Persist naming conventions as a versioned workspace file.
 */
export type SetRulesRequest = {
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Validated rules.
     */
    rules: NamingRules;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * Save a type definition without discarding existing extension properties.
 */
export type SetTypeRequest = {
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Validated property schema and UI hints.
     */
    definition: TypeDefinition;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * One source occurrence; identical bytes do not imply identical meaning.
 */
export type SourceAppearance = {
    /**
     * Sniffed MIME type.
     */
    media_type: string;
    /**
     * Extracted metadata with original field names preserved.
     */
    metadata: {
        [key: string]: unknown;
    };
    /**
     * Observed aliases associated with this occurrence.
     */
    names: Array<SourceName>;
    /**
     * Immutable object content hash.
     */
    object: Digest;
    parent_item_id?: ItemId | null;
    /**
     * Decimal byte count.
     */
    size: string;
    supersedes?: ItemId | null;
};

/**
 * An observed source name and location; not an authority assertion.
 */
export type SourceName = {
    /**
     * Original supplied filename.
     */
    filename: string;
    /**
     * Original relative location.
     */
    folder: string;
    /**
     * RFC 3339 observation time.
     */
    observed_at: string;
    /**
     * Server-recorded source identity.
     */
    supplied_by: string;
};

/**
 * A precise citation that can be reopened independently of current state.
 */
export type SourceReference = {
    digest?: Digest | null;
    /**
     * Stable application item identity; paths remain the portable OKF identity.
     */
    item_id: ItemId;
    /**
     * Relative path at the resolved source revision.
     */
    path: WorkspacePath;
    /**
     * Resolved source revision.
     */
    revision: Revision;
    /**
     * Resolved page, lines, cells, section, or entire source.
     */
    selection: Selection;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * Convert finalized uploads into source cards in the user-selected folder.
 */
export type StartImportRequest = {
    /**
     * Apply the explicit workspace conventions after preview acceptance.
     */
    apply_naming_rules: boolean;
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Relative destination folder; empty for root.
     */
    destination: string;
    /**
     * Durable retry identity.
     */
    idempotency_key: string;
    /**
     * Completed upload slots.
     */
    upload_ids: Array<UploadId>;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * A one-based inclusive line range.
 */
export type TextRange = {
    /**
     * Last line, at least start.
     */
    end: number;
    /**
     * First line, starting at one.
     */
    start: number;
};

/**
 * A user-defined type schema and UI hints.
 */
export type TypeDefinition = {
    /**
     * Exact user-facing OKF type name.
     */
    name: string;
    /**
     * JSON Schema for type-specific properties.
     */
    properties_schema: unknown;
    /**
     * Application format version.
     */
    schema_version: number;
    /**
     * Presentation hints; never authorization rules.
     */
    ui_schema: unknown;
};

/**
 * Edit content against its base revision, invalidating prior review coverage.
 */
export type UpdateItemRequest = {
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Replacement Markdown.
     */
    body: string;
    /**
     * Stable application item identity; paths remain the portable OKF identity.
     */
    item_id: ItemId;
    /**
     * Complete preserved property map.
     */
    properties: {
        [key: string]: unknown;
    };
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * Update workspace presentation metadata at a known revision.
 */
export type UpdateWorkspaceRequest = {
    /**
     * Exact revision on which this change is based; stale writes conflict.
     */
    base_revision: Revision;
    /**
     * Updated purpose.
     */
    description: string;
    /**
     * New display name.
     */
    name: string;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * An authenticated upload slot for a specific source occurrence.
 */
export type Upload = {
    /**
     * Whether expected bytes and digest have been verified.
     */
    complete: boolean;
    /**
     * Upload identity.
     */
    id: UploadId;
    /**
     * Durably retained byte count.
     */
    received_bytes: string;
    /**
     * Same-origin binary PUT target.
     */
    upload_path: string;
    /**
     * Workspace whose permissions and storage scope apply.
     */
    workspace_id: WorkspaceId;
};

/**
 * Identity of one authenticated source upload occurrence.
 */
export type UploadId = string;

/**
 * A named source selection used by a chart or layout.
 */
export type ViewBinding = {
    materialized?: Digest | null;
    /**
     * Dataset or component binding name.
     */
    name: string;
    /**
     * Resolved cited input.
     */
    source: SourceReference;
    /**
     * Declared allowed data transformations; validated against the selected grammar.
     */
    transforms: Array<unknown>;
    /**
     * Column or field units.
     */
    units: {
        [key: string]: string;
    };
};

/**
 * An editable visual artifact with prose and explicit source bindings.
 */
export type ViewDocument = {
    /**
     * Cited input datasets and passages.
     */
    bindings: Array<ViewBinding>;
    /**
     * Readable explanation independent of the renderer.
     */
    description: string;
    /**
     * Declarative renderer grammar.
     */
    grammar: RenderGrammar;
    /**
     * Pinned or explicitly live.
     */
    mode: ViewMode;
    /**
     * App-owned format version, currently 1.
     */
    schema_version: number;
    /**
     * Validated renderer specification with no arbitrary code or external fetching.
     */
    spec: unknown;
    /**
     * Human-readable visual title.
     */
    title: string;
};

/**
 * Pinned historical views and explicit live refresh have different semantics.
 */
export type ViewMode = 'pinned' | 'live';

/**
 * A diagnostic that does not silently discard usable input.
 */
export type Warning = {
    /**
     * Stable diagnostic identifier.
     */
    code: string;
    /**
     * Page, cell, path, or field locator.
     */
    location?: string | null;
    /**
     * Human-readable explanation.
     */
    message: string;
};

/**
 * A user-owned OKF workspace with a resolved head revision.
 */
export type Workspace = {
    /**
     * RFC 3339 creation time.
     */
    created_at: string;
    /**
     * One-line context for people and agents.
     */
    description: string;
    /**
     * Current resolved Git commit.
     */
    head: Revision;
    /**
     * Stable application identity.
     */
    id: WorkspaceId;
    /**
     * Human-selected workspace name.
     */
    name: string;
    /**
     * Whether this principal may only read it.
     */
    read_only: boolean;
};

/**
 * Stable application identity for one user-organized workspace.
 */
export type WorkspaceId = string;

/**
 * A normalized relative workspace path; this alone is not filesystem authorization.
 */
export type WorkspacePath = string;

